contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount) public payable {
        require(address(this).balance >= amount);
        require(amount > 0);

        uint256 cBalanceBefore = address(c).balance;

        bool reverted;
        try c.go{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 cBalanceAfter = address(c).balance;

        // go must not revert, forwards exactly `amount` out, then drains any
        // remaining balance to owner, so c's post-balance is always zero and
        // the amount leaving c is exactly the prior balance plus the amount sent in.
        assert(
            !reverted &&
            cBalanceAfter == 0 &&
            cBalanceBefore + amount - cBalanceAfter == cBalanceBefore + amount
        );
    }

    receive() external payable {}
}

